'use strict';

// MODULES //

import constantFunction from '@stdlib/utils-constant-function';
import { factory as degenerate } from '@stdlib/stats-base-dists-degenerate-logpdf';
import isnan from '@stdlib/math-base-assert-is-nan';
import ln from '@stdlib/math-base-special-ln';
import LN_TWO_PI from '@stdlib/constants-float64-ln-two-pi';
import PINF from '@stdlib/constants-float64-pinf';
import NINF from '@stdlib/constants-float64-ninf';


// MAIN //

/**
* Returns a function for evaluating the natural logarithm of the probability density function (PDF) for a Wald distribution.
*
* @param {PositiveNumber} mu - mean
* @param {NonNegativeNumber} lambda - shape parameter
* @returns {Function} function to evaluate the natural logarithm of the probability density function
*
* @example
* var logpdf = factory( 1.0, 1.0 );
* var y = logpdf( 2.0 );
* // returns ~-2.209
*
* y = logpdf( 0.5 );
* // returns ~-0.129
*/
function factory( mu, lambda ) {
	var A;
	if (
		isnan( mu ) ||
		isnan( lambda ) ||
		mu <= 0.0 ||
		lambda < 0.0
	) {
		return constantFunction( NaN );
	}
	if ( lambda === 0.0 ) {
		return degenerate( mu );
	}
	A = ln( lambda ) - LN_TWO_PI;
	return logpdf;

	/**
	* Evaluates the natural logarithm of the probability density function (PDF) of a Wald distribution.
	*
	* @private
	* @param {number} x - input value
	* @returns {number} evaluated logPDF
	*
	* @example
	* var y = logpdf( 2.0 );
	* // returns <number>
	*/
	function logpdf( x ) {
		var v;
		if ( isnan( x ) ) {
			return NaN;
		}
		if ( x <= 0.0 || x === PINF ) {
			return NINF;
		}
		v = ( x - mu ) / mu;
		return 0.5 * ( A - ( 3.0 * ln( x ) ) - ( ( ( lambda / x ) * v ) * v ) );
	}
}


// EXPORTS //

export default factory;
